<?php
declare(strict_types=1);

namespace Homebox;

/**
 * 관공서 메인 목업 조립기 (2026-09-25)
 *
 * 수집 섹션을 y 순서대로 쌓던 방식은 "소스 나열"이었다(사용자 지적). 메인은 이렇게 짠다:
 *  1) 무엇이 있어야 하나 = 게시된 메인 화면의 채택률(adoption) — 90%+ 필수 · 50%+ 표준 · 그 아래 선택
 *  2) 어디에 두나     = 같은 데이터의 평균 세로 위치 순서
 *  3) 어떻게 생겼나   = 레퍼런스 사이트의 토큰(주색·글꼴·모서리·폭) + 그 화면에서 수집한 메뉴·바로가기·탭 이름
 *  4) 동작           = 비주얼·알림판·배너 캐러셀(자동 재생 + 이전·정지·다음 — KWCAG 2.2.2), 탭(방향키), 메가 메뉴, 검색·전체메뉴 레이어
 *  글·기관·인물은 SampleContent 가상값, 사진은 Samples 라이브러리.
 */
final class MainMockup
{
    /** 스크립트가 실행 중에 만드는 클래스 — CSS 를 덜어 낼 때 지우면 안 된다 (2026-10-12) */
    private const JS_CLASSES = ['mm-cal', 'mm-cal-ev', 'mm-cal-grid', 'mm-count', 'mm-dd', 'mm-fit', 'mm-gnb', 'mm-grid', 'mm-header', 'mm-layer', 'mm-next', 'mm-play', 'mm-prev', 'mm-split-copy', 'mm-track', 'mm-viewport', 'is-open', 'is-lone', 'is-on'];
    /** 메인 채택률 실측 (게시 메인 118곳, 2026-09-25) — 라이브 값이 있으면 route 가 덮는다 */
    public const ADOPTION = [
        'quick_links' => 99, 'news_tabs' => 92, 'search' => 87, 'footer' => 87, 'banner_zone' => 81, 'youtube' => 79,
        'masthead' => 75, 'carousel_controls' => 70, 'events' => 70, 'popup_zone' => 54, 'english' => 58, 'all_menu' => 38,
        'related_sites' => 32, 'login' => 37, 'weather' => 19,
    ];

    private const UTIL = '/로그인|회원가입|날씨|english|사이트맵|검색|메뉴|전체|언어|language|닫기|열기|바로가기$|^홈$|home|sns|페이스북|인스타|블로그|유튜브/iu';

    public static function build(array $tok, array $persona, array $hints, int $seed): array
    {
        $p = $persona; $org = $p['org']; $gov = in_array($p['kind'], ['gov', 'corp'], true) || !SampleContent::isCivic((string) $p['kind']);
        Samples::context($org); // 기관 맞춤 배너 + 앞 시안에서 쓴 이미지는 뒤로(2026-09-26)
        $e = static fn ($s) => htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8');

        // ── 기관 자산: 로고·마스코트(이름으로 정확히)·서명(성별로 고르고 기관장 이름을 서명 이름에 맞춘다 — 사진·이름·서명이 한 사람)
        $emb = Samples::emblem($org); $mascot = Samples::emblem($org, 'mascot');
        $sigs = Samples::find(['signature'], [($p['gender'] ?? '') === 'female' ? '여성' : '남성'], 1, $seed);
        $sig = $sigs ? Samples::view($sigs[0]) : null;
        if ($sig !== null) {
            foreach ((array) $sig['tags'] as $t) { if (preg_match('/^[가-힣]{3}$/u', (string) $t) && !in_array($t, ['남성', '여성'], true)) { $p['name'] = $t; } }
            $p['sig'] = $sig['url'];
        }
        $logo = static fn (string $cls) => $emb ? '<img class="' . $cls . '" src="' . $e($emb['url']) . '" alt="' . $e($org) . '">' : self::govMark(38, 'mm-emblem') . '<span>' . $e($org) . '</span>';

        // ── 메뉴: 수집한 GNB 이름(유틸 링크 제외)이 4개 이상이면 그대로, 아니면 기관 유형 기본 구성
        $gnb = array_values(array_filter((array) ($hints['gnb'] ?? []), static fn ($l) => is_string($l) && mb_strlen($l) >= 2 && mb_strlen($l) <= 9 && !preg_match(self::UTIL, $l)));
        // 헤더 위 유틸·가족 사이트 링크('통합예약·본인인증·○○관광·○○군의회·고향사랑기부제')가 주 메뉴로 들어오던 것 (2026-10-12 MCP 예시 시험)
        $stem = mb_substr((string) $org, 0, max(2, mb_strlen((string) $org) - 1));
        $gnb = array_values(array_filter($gnb, static fn ($l) => !preg_match('/통합예약|본인인증|로그아웃|마이페이지|고향사랑|기부제|글자 ?크기|인쇄|즐겨찾기|(의회|청|관광|도서관|보건소|센터|재단|공단)$/u', $l) && !str_starts_with($l, $stem)));
        $gnb = array_slice(array_values(array_unique($gnb)), 0, 6);
        if (count($gnb) < 4) {
            $gnb = $gov ? ['정책·정보', '알림·소식', '민원·참여', '정보공개', '기관소개'] : ['전자민원', '분야별정보', '참여·소통', '정보공개', '알림마당', $org . '소개'];
        }
        $subs = static function (string $l) use ($org): array {
            return match (true) {
                (bool) preg_match('/민원/u', $l) => ['민원 안내', '민원 신청', '민원 서식', '여권 민원', '자주 묻는 질문'],
                (bool) preg_match('/정보공개/u', $l) => ['정보공개 청구', '사전정보 공표', '업무추진비', '예산·재정', '공공데이터'],
                (bool) preg_match('/알림|소식|뉴스/u', $l) => ['공지사항', '보도자료', '고시·공고', '채용정보', '행사·일정'],
                (bool) preg_match('/참여|소통/u', $l) => ['국민신문고', '제안하기', '설문조사', '주민참여예산', '칭찬합시다'],
                (bool) preg_match('/소개|기관/u', $l) => ['인사말', '연혁', '조직도', '찾아오시는 길', '상징물'],
                (bool) preg_match('/분야|정책/u', $l) => ['복지', '일자리·경제', '안전', '교육·청소년', '문화·관광'],
                default => ['주요 업무', '사업 안내', '자료실', '자주 묻는 질문'],
            };
        };

        // ── 사진 (한 문서 안에서 같은 사진을 두 번 쓰지 않는다)
        $used = []; $all = [];
        $take = static function (array $kinds, int $n, array $tags = []) use ($seed, &$used, &$all): array {
            $r = array_map([Samples::class, 'view'], Samples::find($kinds, $tags, $n, $seed, array_keys($used)));
            if (count($r) < $n) {
                $more = array_map([Samples::class, 'view'], Samples::find($kinds, $tags, $n, $seed + 7, array_column($r, 'id')));
                foreach ($more as $x) { if (count($r) >= $n) { break; } if (!in_array($x['id'], array_column($r, 'id'), true)) { $r[] = $x; } }
            }
            foreach ($r as $x) { $used[$x['id']] = true; $all[$x['id']] = $x; }
            return $r;
        };

        $h = [];
        $h[] = '<a class="mm-skip" href="#mm-main">본문 바로가기</a>';
        // 전자정부 누리집 표지 (75%) — KRDS masthead
        $h[] = '<div class="mm-masthead"><div class="mm-wrap">' . self::govMark(18, 'mm-flag') . '이 누리집은 대한민국 공식 전자정부 누리집입니다.</div></div>';
        // 유틸 + 헤더 + GNB(메가)
        $gnbHtml = '';
        foreach ($gnb as $i => $l) {
            $gnbHtml .= '<li><button type="button" class="mm-gnb-btn" aria-expanded="false" aria-controls="mm-sub' . $i . '">' . $e($l) . '</button><div class="mm-mega" id="mm-sub' . $i . '"><div class="mm-wrap"><strong>' . $e($l) . '</strong><ul>'
                . implode('', array_map(static fn ($s) => '<li><a href="#">' . htmlspecialchars($s, ENT_QUOTES, 'UTF-8') . '</a></li>', $subs($l))) . '</ul></div></div></li>';
        }
        $h[] = '<header class="mm-header"><div class="mm-util"><div class="mm-wrap"><a href="#">로그인</a><a href="#">회원가입</a><a href="#" lang="en">ENGLISH</a></div></div>'
            . '<div class="mm-wrap mm-bar"><h1 class="mm-h1"><a class="mm-logo" href="#">' . $logo('mm-logo-img') . '</a></h1>' // 메인 h1 = 기관 로고(판정 D: h1 없음 -2, 2026-10-14)
            . '<nav class="mm-gnb" aria-label="주 메뉴"><ul>' . $gnbHtml . '</ul></nav>'
            . '<div class="mm-tools"><button type="button" class="mm-tool" data-open="mm-search" aria-label="통합검색">' . self::ico('search') . '</button><button type="button" class="mm-tool" data-open="mm-sitemap" aria-label="전체메뉴">' . self::ico('menu') . '</button></div></div></header>';

        // ── 본문 = 레퍼런스 메인 화면의 행 구성을 그대로 따른다 (MainLayout)
        $fams = [];
        foreach ((array) ($hints['sections'] ?? []) as $sx) {
            $st = is_string($sx['structure'] ?? null) ? (json_decode($sx['structure'], true) ?: []) : (array) ($sx['structure'] ?? []);
            $cf = WebFont::canonical($st['font']['family'] ?? null);
            if ($cf !== null) { $fams[$cf] = ($fams[$cf] ?? 0) + 1; }
        }
        arsort($fams);
        $mainFont = WebFont::canonical((string) preg_replace("/^'([^']+)'.*/", '$1', (string) ($tok['font'] ?? '')));
        if (empty($tok['font_lock'])) {
            $mainFont = $fams ? (string) array_key_first($fams) : WebFont::canonical((string) preg_replace("/^'([^']+)'.*/", '$1', (string) ($tok['font'] ?? '')));
            $tok['font'] = WebFont::stack($mainFont);
        }
        $lay = MainLayout::render((array) ($hints['sections'] ?? []), $p, $take, (int) ($hints['vw'] ?? 1920), (int) ($tok['container'] ?? 1280));
        $h[] = '<main id="mm-main">' . $lay['html'] . '</main>';

        // 푸터 (87%) — 관련사이트 드롭다운(32%) + 정책 링크 + 주소 + 인증
        $rel = ['중앙행정기관', '지방자치단체', '공공기관', '유관기관'];
        // 레퍼런스 푸터에 링크가 많으면(20+) 사이트맵 열 — 메뉴 이름을 열 제목으로 (LH·보훈부 비교 검수 B3, 2026-09-25)
        $fsec = null;
        foreach ((array) ($hints['sections'] ?? []) as $sx) { if (($sx['type'] ?? '') === 'footer') { $fsec = $sx; } }
        $fst = $fsec ? (is_string($fsec['structure'] ?? null) ? (json_decode($fsec['structure'], true) ?: []) : (array) ($fsec['structure'] ?? [])) : [];
        $sitemap = '';
        if ((int) ($fst['links']['n'] ?? 0) >= 20 && (int) ($fsec['h'] ?? 0) >= 400) { // 높이 400+ 인 푸터만(LH 1,041px) — 한 줄 푸터(부천 208px)엔 붙이지 않는다
            $sitemap = '<nav class="mm-sitemap" aria-label="사이트맵"><h2>' . $e($org) . '</h2><div class="mm-sitemap-cols">' . implode('', array_map(static fn ($g) => '<div><h3>' . $e($g) . '</h3><ul>' . implode('', array_map(static fn ($x) => '<li><a href="#">' . $e($x) . '</a></li>', $subs($g))) . '</ul></div>', $gnb)) . '</div></nav>';
        }
        $lightFoot = array_key_exists('footer_bg', (array) ($hints['look'] ?? [])) && ($hints['look']['footer_bg'] ?? null) === null; // 캡처 아래쪽에 어두운 띠가 없다 = 밝은 푸터
        // 레퍼런스 푸터가 낮으면(서울 159px) 로고를 왼쪽에 둔 두 단 푸터 — 세 단으로 쌓으면 300px 이 넘어 전체 높이 +5%(2026-10-13 D7)
        $compactFoot = $fsec && $sitemap === '' && (int) ($fsec['h'] ?? 0) > 0 && (int) $fsec['h'] < 260;
        $h[] = '<footer class="mm-footer' . ($lightFoot ? ' is-light' : '') . ($compactFoot ? ' is-compact' : '') . '"><div class="mm-wrap">' . $sitemap . '<div class="mm-foot-top"><ul class="mm-policy"><li><a href="#" class="is-strong">개인정보처리방침</a></li><li><a href="#">저작권정책</a></li><li><a href="#">이메일무단수집거부</a></li><li><a href="#">찾아오시는 길</a></li><li><a href="#">누리집 이용안내</a></li></ul>'
            . '<div class="mm-rel">' . implode('', array_map(static fn ($r, $i) => '<div class="mm-dd"><button type="button" aria-expanded="false" aria-controls="mm-rel' . $i . '">' . $r . self::ico('down') . '</button><ul id="mm-rel' . $i . '" hidden><li><a href="#">' . $r . ' 누리집 1</a></li><li><a href="#">' . $r . ' 누리집 2</a></li><li><a href="#">' . $r . ' 누리집 3</a></li></ul></div>', array_slice($rel, 0, 3), [0, 1, 2])) . '</div></div>'
            . '<div class="mm-foot-brand">' . $logo('mm-foot-logo') . ($mascot ? '<img class="mm-mascot" src="' . $e($mascot['url']) . '" alt="' . $e($org) . ' 마스코트">' : '') . '</div>'
            . '<address>([우편번호]) [주소] · 대표전화 [000-000-0000]</address><div class="mm-foot-btm"><p>© [기관명]. All rights reserved.</p><span class="mm-wa">웹 접근성 품질인증</span></div></div></footer>';

        // 검색 레이어 · 전체메뉴
        $h[] = '<div class="mm-layer" id="mm-search" role="dialog" aria-modal="true" aria-label="통합검색" hidden><div class="mm-layer-box"><form class="mm-sform" role="search"><label for="mm-q" class="mm-sr">검색어</label><input id="mm-q" type="search" placeholder="검색어를 입력하세요"><button type="submit">' . self::ico('search') . '<span class="mm-sr">검색</span></button></form><p class="mm-popular">인기 검색어 <a href="#">여권</a><a href="#">채용</a><a href="#">주민등록</a><a href="#">축제</a></p><button type="button" class="mm-close" data-close aria-label="닫기">' . self::ico('close') . '</button></div></div>';
        $h[] = '<div class="mm-layer" id="mm-sitemap" role="dialog" aria-modal="true" aria-label="전체메뉴" hidden><div class="mm-layer-box mm-sitemap"><h2>전체메뉴</h2><div class="mm-smap">'
            . implode('', array_map(static fn ($l) => '<div><strong>' . htmlspecialchars($l, ENT_QUOTES, 'UTF-8') . '</strong><ul>' . implode('', array_map(static fn ($s) => '<li><a href="#">' . htmlspecialchars($s, ENT_QUOTES, 'UTF-8') . '</a></li>', $subs($l))) . '</ul></div>', $gnb))
            . '</div><button type="button" class="mm-close" data-close aria-label="닫기">' . self::ico('close') . '</button></div></div>';

        $body = SampleContent::fill(implode("\n", $h), $p, $seed, 'main');
        // 빈 링크(#) 대신 본문 앵커 — 눌러도 아무 데도 안 가던 것(판정 '링크 90% 이상 #' -2, 2026-10-14)
        $body = str_replace('href="#"', 'href="#mm-main"', $body);
        $doc = "<!doctype html>\n<html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>" . $e($org) . "</title>\n" . WebFont::head([$mainFont]) . "\n<style>" . CssPrune::prune(self::css($tok), $body, 'mm-', self::JS_CLASSES) . MockSearch::CSS . "</style></head>\n<body>\n" . $body . "\n<script>" . self::js() . "</script><script>" . MockSearch::JS . "</script>\n</body></html>";

        $composition = [
            ['block' => 'masthead', 'label' => '전자정부 누리집 표지', 'adoption' => self::ADOPTION['masthead']],
            ['block' => 'header', 'label' => '헤더·메가 메뉴·통합검색·전체메뉴', 'adoption' => self::ADOPTION['search'], 'source' => count((array) ($hints['gnb'] ?? [])) >= 4 ? 'collected' : 'default'],
            ['block' => 'body', 'label' => '본문 — 레퍼런스 메인의 행 구성(칸 비율·섹션 모양)', 'rows' => $lay['composition'], 'added' => $lay['added']],
            ['block' => 'footer', 'label' => '푸터·관련사이트·정책 링크', 'adoption' => self::ADOPTION['footer']],
        ];
        Samples::remember(array_keys($all));
        // 메인이 실제로 쓴 기관장 이름·서명 — 홈페이지 한 벌의 서브가 같은 사람을 쓰게 돌려준다
        return ['html' => $doc, 'composition' => $composition, 'samples' => array_values($all), 'person' => array_filter(['name' => $p['name'] ?? null, 'sig' => $p['sig'] ?? null, 'name_locked' => isset($p['sig'])])];
    }

    /**
     * 기본 로고 심볼 = 대한민국 정부상징 원본 SVG (사용자 지시 2026-09-25 — "니 멋대로 만들지 말고 이걸 써").
     * 출처: Wikimedia Commons "Emblem_of_the_Government_of_the_Republic_of_Korea.svg" → api/data/gov-emblem.svg (원본 그대로, 크기·클래스만 바꾼다)
     * 기관 로고를 받기 전 자리표시다. 실제 사용은 정부상징 관련 규정을 따른다.
     */
    public static function govMark(int $size = 40, string $cls = ''): string
    {
        static $svg = null;
        $svg ??= (string) @file_get_contents(dirname(__DIR__) . '/data/gov-emblem.svg');
        if ($svg === '') { return ''; }
        return (string) preg_replace('/<svg[^>]*?viewBox="([^"]+)"[^>]*>/', '<svg class="' . $cls . '" width="' . $size . '" height="' . $size . '" viewBox="$1" role="img" aria-label="정부상징" focusable="false" xmlns="http://www.w3.org/2000/svg">', $svg, 1);
    }

    public static function iconFor(string $l): string
    {
        return match (true) {
            (bool) preg_match('/질문|FAQ|문의|도움/u', $l) => 'faq',
            (bool) preg_match('/통계|지표|현황|데이터/u', $l) => 'chart',
            (bool) preg_match('/조직|부서|직원|전화번호/u', $l) => 'org',
            (bool) preg_match('/상담|콜센터|대표전화|120/u', $l) => 'phone',
            (bool) preg_match('/보도|소식|뉴스|브리핑|공지|알림/u', $l) => 'news',
            (bool) preg_match('/교육|학습|강좌|도서관|자료실|자료/u', $l) => 'book',
            (bool) preg_match('/환경|기후|녹색|공원|숲/u', $l) => 'leaf',
            (bool) preg_match('/주택|부동산|건축|토지|임대|청약/u', $l) => 'home',
            (bool) preg_match('/제안|신고|참여/u', $l) => 'mega',
            (bool) preg_match('/청년|어르신|아동|청소년|가족|어린이|주민|시민|국민/u', $l) => 'people',
            (bool) preg_match('/예산|결산|계약|입찰|재정/u', $l) => 'coin',
            (bool) preg_match('/민원|서식|신청|증명/u', $l) => 'doc',
            (bool) preg_match('/여권|주민|신분/u', $l) => 'id',
            (bool) preg_match('/채용|일자리|취업|구인/u', $l) => 'work',
            (bool) preg_match('/예약|일정|행사|달력/u', $l) => 'cal',
            (bool) preg_match('/복지|건강|의료|돌봄/u', $l) => 'heart',
            (bool) preg_match('/교통|버스|주차/u', $l) => 'bus',
            (bool) preg_match('/세|납부|요금|재정/u', $l) => 'coin',
            (bool) preg_match('/정보공개|검색|법령/u', $l) => 'search',
            (bool) preg_match('/관광|문화|지도|길/u', $l) => 'pin',
            (bool) preg_match('/안전|재난/u', $l) => 'shield',
            (bool) preg_match('/제안|신고|참여|브리핑|보도/u', $l) => 'mega',
            default => 'grid',
        };
    }

    public static function icon(string $n): string { return self::ico($n); }

