    private static function css(array $t): string
    {
        $pr = $t['primary'] ?? '#1D4ED8'; $r = (int) ($t['radius'] ?? 8); $w = (int) ($t['container'] ?? 1280); $ls = LayoutStats::main(); $w = min((int) ($ls['container_w']['max'] ?? 1720), max($w, (int) ($ls['container_w']['p25'] ?? 1280))); $w = max($w, ReplicaKit::MIN_W); /* PC 본문 최소 1400(2026-10-11) */ $f = $t['font'] ?? "'Pretendard GOV',system-ui,sans-serif";
        // 타이포: 수집값을 쓰되 목업에 안전한 범위로 자른다. 행간 1.2 미만은 측정 오차(한 줄 요소)라 쓰지 않는다
        $sc = (array) ($t['type'] ?? []);
        $pick = static function (array $keys, int $lo, int $hi) use ($sc): ?array {
            foreach ($keys as $k) { $v = $sc[$k] ?? null; if (is_array($v) && isset($v['size']) && $v['size'] >= $lo && $v['size'] <= $hi) { return $v; } }
            return null;
        };
        $body = $pick(['body', 'link'], 14, 20); $nav = $pick(['nav'], 15, 24); $hd = $pick(['h2', 'h4', 'h3', 'subtitle'], 18, 34);
        $vars = '';
        if ($body) { $vars .= '--fs-body:' . (int) $body['size'] . 'px;--fw-body:' . min(600, max(300, (int) ($body['weight'] ?? 400))) . ';--ls-body:' . round((float) ($body['letter_spacing'] ?? 0), 3) . 'em;' . (($body['line_height'] ?? 0) >= 1.3 ? '--lh-body:' . round((float) $body['line_height'], 2) . ';' : ''); }
        if ($nav) { $vars .= '--fs-nav:' . (int) $nav['size'] . 'px;--fw-nav:' . min(800, max(500, (int) ($nav['weight'] ?? 700))) . ';'; }
        if ($hd) { $vars .= '--fs-h:' . (int) $hd['size'] . 'px;--fw-h:' . min(800, max(500, (int) ($hd['weight'] ?? 700))) . ';--ls-h:' . round((float) ($hd['letter_spacing'] ?? -0.02), 3) . 'em;'; }
        // 재현 연습 통계(api/data/layout-stats.json) — 사이트 값이 없거나 너무 작을 때의 기본값·하한
        $med = static fn (string $k, float $d) => (float) ($ls[$k]['median'] ?? $d);
        $vars .= '--gap-row:' . (int) round($med('section_gap', 40) / 2) . 'px;--gap-cell:' . (int) $med('cell_gap', 24) . 'px;--hs-min:' . (int) ($ls['title_font']['p25'] ?? 20) . 'px;--mb-h:' . (int) $med('title_margin', 14) . 'px;--cr-card:' . max($r, (int) $med('card_radius', 8)) . 'px;--qi:' . ((int) $med('quick_icon', 50) + 6) . 'px;--q-label:' . (int) $med('quick_label', 15) . 'px;';
        return ":root{{$vars}--p:{$pr};--p-d:color-mix(in srgb,var(--p) 78%,#000);--p-l:color-mix(in srgb,var(--p) 10%,#fff);--r:{$r}px;--w:{$w}px;--fg:#1E2124;--mute:#6D7882;--line:#E2E6EC;--bg2:#F4F6F9}"
            . "*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;font-family:{$f};color:var(--fg);font-size:var(--fs-body,16px);font-weight:var(--fw-body,400);letter-spacing:var(--ls-body,0);line-height:var(--lh-body,1.6);word-break:keep-all}a{color:inherit;text-decoration:none}ul{list-style:none;margin:0;padding:0}button{font:inherit;color:inherit;cursor:pointer}h2{margin:0}"
