epeat(3,1fr);gap:12px;margin:0;padding:28px;list-style:none;background:var(--p-l);border-radius:var(--cr);min-height:360px;align-content:center}.mm-dist button{width:100%;height:64px;border:1px solid var(--line);border-radius:14px;background:#fff;font-size:16px;font-weight:600;color:var(--fg)}.mm-dist button[aria-pressed=true]{background:var(--p);color:#fff;border-color:var(--p)}.mm-member form{display:flex;align-items:center;height:52px;border:2px solid var(--p);border-radius:999px;padding:0 6px 0 20px;margin-bottom:20px}.mm-member input{flex:1;border:0;outline:0;font-size:15px;min-width:0;background:none}.mm-member form button{width:40px;height:40px;border:0;border-radius:50%;background:var(--p);color:#fff;display:grid;place-items:center}.mm-member form button svg{width:18px;height:18px}.mm-member-card{display:flex;gap:24px;align-items:flex-start}.mm-member-img{flex:none;width:150px;aspect-ratio:3/4;border-radius:10px;overflow:hidden}.mm-member-img img{width:100%;height:100%;object-fit:cover}.mm-member dl{display:grid;grid-template-columns:auto 1fr;gap:10px 16px;margin:0;font-size:15px}.mm-member dt{color:var(--mute)}.mm-member dd{margin:0}.mm-member-btns{display:flex;gap:10px;margin:20px 0 0}.mm-hero.is-narrow .mm-copy h2{font-size:26px;line-height:1.3}.mm-hero.is-narrow .mm-copy>p:not(.mm-kicker){display:none}.mm-hero.is-narrow .mm-copy{max-width:88%}.mm-store{display:inline-flex;align-items:center;height:48px;padding:0 20px;border-radius:10px;background:#fff;color:var(--fg);font-weight:700;font-size:15px}.mm-mag-cover{flex:none;width:42%;aspect-ratio:3/4;border-radius:8px;overflow:hidden;box-shadow:0 8px 20px rgba(0,0,0,.15)}.mm-mag-cover img{width:100%;height:100%;object-fit:cover}.mm-infocards.is-big li a{min-height:170px;justify-content:space-between;padding:26px}.mm-infocards.is-big strong{font-size:19px}.mm-infocards.is-big p{margin:8px 0 0;color:var(--mute);font-size:14px;line-height:1.55}"
