    private static function js(): string
    {
        return str_replace('__ICO__', (string) json_encode(['pause' => '<path d="' . self::icoPath('pause') . '"/>', 'play' => '<path d="' . self::icoPath('play') . '"/>']), <<<'JS'
(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const ico=__ICO__;
document.querySelectorAll('[data-carousel]').forEach(c=>{const step=c.hasAttribute('data-step');const track=c.querySelector('.mm-track');const items=track?[...track.children]:[];if(!items.length)return; // 빈 캐러셀은 건너뛴다(2026-10-14 국민대 레퍼런스 스크립트 오류)
const cnt=c.querySelector('.mm-count b'),tot=c.querySelector('.mm-count span');const play=c.querySelector('.mm-play');let i=0,timer=null,paused=reduce;
 const per=()=>step?Math.max(1,Math.round(c.querySelector('.mm-viewport').clientWidth/items[0].getBoundingClientRect().width)):1;
 const pages=()=>step?Math.max(1,items.length-per()+1):items.length;if(tot)tot.textContent=pages();
 const show=n=>{i=(n+pages())%pages();if(step){const w=items[0].getBoundingClientRect().width+(parseFloat(getComputedStyle(items[0].parentElement).columnGap)||16);track.style.transform='translateX('+(-i*w)+'px)';}else{items.forEach((el,k)=>el.hidden=k!==i);if(c.hasAttribute('data-sync'))c.querySelectorAll('.mm-split-copy').forEach((el,k)=>el.hidden=k!==i);}if(cnt)cnt.textContent=i+1;c.querySelectorAll('[data-go]').forEach((x,k)=>x.setAttribute('aria-current',k===i));};c._show=show;
 const run=()=>{clearInterval(timer);if(!paused)timer=setInterval(()=>show(i+1),+c.dataset.interval||5000);};
 const setPaused=v=>{paused=v;if(play){play.setAttribute('aria-pressed',v);play.dataset.base=play.dataset.base||play.getAttribute('aria-label').replace(/ 자동 재생 정지$/,'');play.setAttribute('aria-label',play.dataset.base+(v?' 자동 재생 시작':' 자동 재생 정지'));play.querySelector('svg').innerHTML=v?ico.play:ico.pause;}run();};
 c.querySelector('.mm-prev')?.addEventListener('click',()=>{show(i-1);run();});c.querySelector('.mm-next')?.addEventListener('click',()=>{show(i+1);run();});play?.addEventListener('click',()=>setPaused(!paused));
 c.addEventListener('focusin',()=>clearInterval(timer));c.addEventListener('focusout',()=>run());c.addEventListener('mouseenter',()=>clearInterval(timer));c.addEventListener('mouseleave',()=>run());
 addEventListener('resize',()=>{if(tot)tot.textContent=pages();show(Math.min(i,pages()-1));});setPaused(paused);show(0);});
document.querySelectorAll('[role=tablist]').forEach(tl=>{const tabs=[...tl.querySelectorAll('[role=tab]')];const sel=t=>{tabs.forEach(x=>{const on=x===t;x.setAttribute('aria-selected',on);x.tabIndex=on?0:-1;document.getElementById(x.getAttribute('aria-controls')).hidden=!on;});t.focus();};
 tabs.forEach((t,k)=>{t.addEventListener('click',()=>sel(t));t.addEventListener('keydown',e=>{const d={ArrowRight:1,ArrowLeft:-1}[e.key];if(d){e.preventDefault();sel(tabs[(k+d+tabs.length)%tabs.length]);}if(e.key==='Home'){e.preventDefault();sel(tabs[0]);}if(e.key==='End'){e.preventDefault();sel(tabs[tabs.length-1]);}});});});
const gnb=[...document.querySelectorAll('.mm-gnb>ul>li')];const closeG=()=>gnb.forEach(li=>{li.classList.remove('is-open');li.querySelector('button').setAttribute('aria-expanded','false');});
gnb.forEach(li=>{const b=li.querySelector('button');const open=()=>{closeG();li.classList.add('is-open');b.setAttribute('aria-expanded','true');};li.addEventListener('mouseenter',open);b.addEventListener('click',()=>li.classList.contains('is-open')?closeG():open());li.addEventListener('focusin',open);});
document.querySelector('.mm-header')?.addEventListener('mouseleave',closeG);
let last=null;const openL=id=>{const l=document.getElementById(id);last=document.activeElement;l.hidden=false;l.querySelector('input,button,a')?.focus();};const closeL=l=>{l.hidden=true;last?.focus();};
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openL(b.dataset.open)));
document.querySelectorAll('.mm-layer').forEach(l=>{l.addEventListener('click',e=>{if(e.target===l||e.target.closest('[data-close]'))closeL(l);});});
const fitAll=()=>document.querySelectorAll('.mm-fit').forEach(f=>{const k=[...f.children];if(!k.length)return;k.forEach(c=>c.hidden=false);const g=f.closest('.mm-grid');if(!g||g.children.length<2){f.classList.add('is-lone');return;}f.style.minHeight=k[0].offsetHeight+'px';const b=f.getBoundingClientRect().bottom;k.forEach((c,i)=>{if(i&&c.getBoundingClientRect().bottom>b+1)c.hidden=true;});});fitAll();addEventListener('load',fitAll);addEventListener('resize',fitAll);
// 칸 높이 상한(레퍼런스 1.15배) 안에서 넘치면 잘라 버리지 않고 맞춘다(2026-10-14 판정 '잘림' 치명): ① 목록 뒤 항목 숨김 ② 가장 큰 그림을 남은 높이로 ③ 56px 아래면 그림을 빼고 글만. 1024 미만(상한 없음)이면 되돌린다
const capped=new Set();
const capFit=()=>{if(innerWidth<1024){capped.forEach(x=>{if(x.tagName==='LI')x.hidden=false;else{x.style.height=x.style.aspectRatio=x.style.minHeight=x.style.display='';}});capped.clear();return;}document.querySelectorAll('.mm-row .mm-grid>*,.mm-row--full>.mm-wrap>.mm-cell').forEach(c=>{if(getComputedStyle(c).overflow!=='hidden')return;const over=()=>{const cb=c.getBoundingClientRect().bottom;let w=c.scrollHeight-c.clientHeight;c.querySelectorAll('a,button,h2,h3,p,li,span,strong,dd,td').forEach(k=>{if(k.offsetParent===null)return;const r=k.getBoundingClientRect();if(!r.height)return;if(r.bottom-cb>w)w=r.bottom-cb;for(let a=k.parentElement;a&&a!==c;a=a.parentElement){if(getComputedStyle(a).overflowY!=='visible'){const d=r.bottom-a.getBoundingClientRect().bottom;if(d>w&&d<r.height+1)w=d;}}});return w;};if(over()<=1)return;[...c.querySelectorAll('ul,ol')].filter(u=>u.children.length>1&&u.offsetParent!==null&&!u.closest('.mm-cell-head,[role=tablist],.mm-sns,.mm-track,[data-carousel] .mm-viewport')).forEach(u=>{const k=[...u.children].filter(x=>!x.hidden);for(let i=k.length-1;i>0&&over()>1;i--){const before=over();k[i].hidden=true;if(over()>=before){k[i].hidden=false;break;}capped.add(k[i]);}});/* 숨겨도 안 줄면(한 줄 격자·레일) 멈춘다 — 바로가기 8칸이 1칸만 남던 것(2026-10-14) */for(let t=0;t<3&&over()>1;t++){c.querySelectorAll('.mm-fit').forEach(f=>f.style.minHeight='0');const m=[...c.querySelectorAll('img,.mm-promo,.mm-thumb,.mm-track,.mm-bn-stack li a')].filter(x=>!x.closest('.mm-cell-head')&&x.offsetHeight>60&&!(x.tagName==='IMG'&&x.closest('.mm-bn-stack li a'))).sort((a,b)=>b.offsetHeight-a.offsetHeight)[0];if(!m)return;const h=m.offsetHeight-over()-2;const cls=m.classList[0];const all=cls?[...c.querySelectorAll('.'+cls)]:[m];if(h<56&&m.tagName==='IMG'){all.forEach(x=>{const w=x.closest('.mm-thumb-wrap')||x;w.style.display='none';capped.add(w);});continue;}all.forEach(x=>{x.style.aspectRatio='auto';x.style.minHeight='0';x.style.height=Math.max(56,h)+'px';capped.add(x);});}});};
capFit();addEventListener('load',capFit);addEventListener('resize',capFit);['click','keyup'].forEach(t=>document.addEventListener(t,()=>requestAnimationFrame(capFit)));document.querySelectorAll('img').forEach(i=>{if(!i.complete)i.addEventListener('load',capFit,{once:true});});
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>b.closest('[data-carousel]')._show(+b.dataset.go)));
document.querySelectorAll('.mm-cal').forEach(cal=>{const out=cal.querySelector('.mm-cal-ev');cal.querySelectorAll('.mm-cal-grid button').forEach(b=>b.addEventListener('click',()=>{cal.querySelectorAll('.mm-cal-grid button').forEach(x=>x.classList.toggle('is-on',x===b));if(out)out.innerHTML='<time>10.'+String(b.textContent).padStart(2,'0')+'</time> '+(b.dataset.ev||'등록된 행사가 없습니다');}));});
document.querySelectorAll('.mm-dd').forEach(d=>{const b=d.querySelector('button'),u=d.querySelector('ul');b.addEventListener('click',()=>{const o=u.hidden;document.querySelectorAll('.mm-dd ul').forEach(x=>{x.hidden=true;x.previousElementSibling.setAttribute('aria-expanded','false');});u.hidden=!o;b.setAttribute('aria-expanded',o);});});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;closeG();document.querySelectorAll('.mm-layer:not([hidden])').forEach(closeL);document.querySelectorAll('.mm-dd ul').forEach(x=>x.hidden=true);});
document.addEventListener('click',e=>{if(!e.target.closest('.mm-dd'))document.querySelectorAll('.mm-dd ul').forEach(x=>x.hidden=true);if(!e.target.closest('.mm-header'))closeG();});
document.querySelectorAll('form[role=search]').forEach(f=>f.addEventListener('submit',e=>e.preventDefault()));})();
JS);
    }

    private static function icoPath(string $n): string
    {
        preg_match('/ d="([^"]+)"/', MaterialIcon::svg($n), $m);
        return $m[1] ?? '';
    }
}
